from datetime import date, timedelta


def recur(start: str, rule: str, count: int) -> list[str]:
    y, m, d = map(int, start.split("-"))
    start_date = date(y, m, d)
    tokens = rule.split()

    def fmt(dt):
        return dt.isoformat()

    results = []

    if tokens[0] == "DAILY":
        k = int(tokens[1])
        n = 0
        while len(results) < count:
            dt = start_date + timedelta(days=n * k)
            results.append(fmt(dt))
            n += 1

    elif tokens[0] == "WEEKLY":
        k = int(tokens[1])
        days = tokens[2].split(",")
        wd_idx = {"MO": 0, "TU": 1, "WE": 2, "TH": 3, "FR": 4, "SA": 5, "SU": 6}
        wanted = sorted(wd_idx[x] for x in days)
        # Monday of week 0
        week0_monday = start_date - timedelta(days=start_date.weekday())
        wk = 0
        while len(results) < count:
            if wk % k == 0:
                monday = week0_monday + timedelta(weeks=wk)
                for wd in wanted:
                    dt = monday + timedelta(days=wd)
                    if dt >= start_date:
                        results.append(fmt(dt))
                        if len(results) == count:
                            break
            wk += 1

    elif tokens[0] == "MONTHLY":
        k = int(tokens[1])
        if len(tokens) == 3:
            # MONTHLY K D
            spec = tokens[2]
            start_month = start_date.year * 12 + (start_date.month - 1)
            off = 0
            while len(results) < count:
                mi = start_month + off
                if off % k == 0:
                    yy = mi // 12
                    mm = mi % 12 + 1
                    if spec == "-1":
                        if mm == 12:
                            last = date(yy, 12, 31)
                        else:
                            last = date(yy, mm + 1, 1) - timedelta(days=1)
                        dt = last
                    else:
                        day = int(spec)
                        try:
                            dt = date(yy, mm, day)
                        except ValueError:
                            dt = None
                    if dt is not None and dt >= start_date:
                        results.append(fmt(dt))
                        if len(results) == count:
                            break
                off += 1
        else:
            # MONTHLY K N WD
            n = int(tokens[2])
            wd_idx = {"MO": 0, "TU": 1, "WE": 2, "TH": 3, "FR": 4, "SA": 5, "SU": 6}
            wd = wd_idx[tokens[3]]
            start_month = start_date.year * 12 + (start_date.month - 1)
            off = 0
            while len(results) < count:
                mi = start_month + off
                if off % k == 0:
                    yy = mi // 12
                    mm = mi % 12 + 1
                    first = date(yy, mm, 1)
                    # first occurrence of weekday wd in month
                    delta = (wd - first.weekday()) % 7
                    first_occ = first + timedelta(days=delta)
                    # last day of month
                    if mm == 12:
                        last = date(yy, 12, 31)
                    else:
                        last = date(yy, mm + 1, 1) - timedelta(days=1)
                    occs = []
                    cur = first_occ
                    while cur <= last:
                        occs.append(cur)
                        cur += timedelta(days=7)
                    if n == -1:
                        dt = occs[-1]
                    elif n - 1 < len(occs):
                        dt = occs[n - 1]
                    else:
                        dt = None
                    if dt is not None and dt >= start_date:
                        results.append(fmt(dt))
                        if len(results) == count:
                            break
                off += 1

    elif tokens[0] == "YEARLY":
        k = int(tokens[1])
        mm, dd = map(int, tokens[2].split("-"))
        start_year = start_date.year
        i = 0
        while len(results) < count:
            yy = start_year + i
            if i % k == 0:
                try:
                    dt = date(yy, mm, dd)
                except ValueError:
                    dt = None
                if dt is not None and dt >= start_date:
                    results.append(fmt(dt))
                    if len(results) == count:
                        break
            i += 1

    return results
